import torch

def gen_inputs(ctx, device):
    data_shape = ctx['data__shape']
    data_dtype = getattr(torch, ctx['data__dtype'])
    total = data_shape[0]
    max_len = ctx['batch_sizes__shape'][0]
    base = total // max_len
    rem = total % max_len
    batch_sizes = torch.full((max_len,), base, dtype=torch.int64)
    if rem > 0:
        batch_sizes[:rem] = base + 1
    data = torch.randn(*data_shape, dtype=data_dtype, device=device)
    return {'data': data, 'batch_sizes': batch_sizes}

def run(data, batch_sizes, batch_first, padding_value, total_length):
    return torch.ops.aten._pad_packed_sequence(data, batch_sizes, batch_first, padding_value, total_length)
